    /// <summary>
    /// Create a WGPUInstance
    /// <para/>
    /// Calls <c>wgpuCreateInstance</c>.
    /// </summary>
    /// <returns>
    /// This value is <c>ReturnedWithOwnership</c>.
    /// </returns>
    public static WGPUInstance wgpuCreateInstance(in WGPUInstanceDescriptor descriptor)
    {
        fixed (WGPUInstanceDescriptor* __descriptor = &descriptor)
        {
            return wgpuCreateInstance(__descriptor);
        }
    }

    /// <summary>
    /// Returns the "procedure address" (function pointer) of the named function.
    /// The result must be cast to the appropriate proc pointer type.
    /// <para/>
    /// Calls <c>wgpuGetProcAddress</c>.
    /// </summary>
    public static delegate* unmanaged[Cdecl]<void> wgpuGetProcAddress(ReadOnlySpan<byte> procName)
    {
        fixed (byte* __procName = procName)
        {
            return wgpuGetProcAddress(new WGPUStringView(__procName, (nuint)procName.Length));
        }
    }

    /// <summary>
    /// Returns the "procedure address" (function pointer) of the named function.
    /// The result must be cast to the appropriate proc pointer type.
    /// <para/>
    /// Calls <c>wgpuGetProcAddress</c>.
    /// </summary>
    public static delegate* unmanaged[Cdecl]<void> wgpuGetProcAddress(string? procName)
    {
        using Utf8Scratch __procName = new(procName, stackalloc byte[Utf8Scratch.StackBufferSize]);
        return wgpuGetProcAddress(__procName.View);
    }
}
